namespace ghidra.app.util.viewer.field;

using ghidra.app.nav;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.util;



public class ImageFactoryFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES = new Class[] { typeof(ImageFactoryField) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable navigatable,
			ProgramLocation location, MouseEvent mouseEvent, ServiceProvider serviceProvider) {
		if (mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}

		if (mouseEvent.getClickCount() == 1) {
			return handleSingleClick(mouseEvent, navigatable, location);
		}

		return false;
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}

	private bool handleSingleClick(MouseEvent mouseEvent, Navigatable navigatable,
			ProgramLocation location) {

		Program program = navigatable.getProgram();
		Listing listing = program.getListing();
		CodeUnit codeUnit = listing.getCodeUnitContaining(location.getAddress());
		if (codeUnit is Data) {
			Data data = (Data) codeUnit;
			object value = data.getValue();
			if (value is Playable) {
				((Playable) value).clicked(mouseEvent);
				return true;
			}
		}

		return false;
	}
}
